<template>
  <el-dialog
    :title="title"
    :visible.sync="visible"
    :width="width"
    :center="true"
    :modal="false"
    :fullscreen="isMobile ? true : fullscreen"
    :top="dTop"
    @close="onDialogClose"
    class="marker-dialog-wrapper"
    :class="isMobile ? 'marker-mobile-dialog-wrapper' : ''"
    :destroy-on-close="false"
  >
    <div class="marker-dialog">
      <div class="marker-dialog-body">
        <div
          class="video-marker"
          ref="videoMarker"
          id="iot-camera-dialog-video-marker"
          v-if="result"
        >
          <EasyPlayer
            :videoUrl="videoUrl"
            ref="camera_player"
            :aspect="aspect"
            :onDemand="true"
            :autoplay="autoplay"
            :muted="muted"
            element-loading-text="加载中..."
            element-loading-background="#000"
            :fluent="fluent"
            :stretch="stretch"
            :live="live"
            @error="onPlayError"
            class="player"
          />
        </div>
        <el-empty description="获取播放地址中..." v-else></el-empty>
      </div>
    </div>
  </el-dialog>
</template>
<script>
import EasyPlayer from '@easydarwin/easyplayer'
import { isMobile } from '@/utils/tools'
import {
  // eslint-disable-next-line no-unused-vars
  getDeviceInfo,
  getCameraLiveUrl,
} from '@/api/iot'
export default {
  name: 'CameraShow',
  components: {
    EasyPlayer,
  },
  data() {
    return {
      markerInfo: null,
      title: '',
      width: '780px',
      visible: false,
      fullscreen: false,
      dTop: '',

      videoUrl: '',
      mode: '4',
      aspect: '16:9',
      muted: false,
      autoplay: false,
      fluent: false,
      stretch: false,
      live: false,
      playerType: 'easyplayer',
      result: null,
      ys7Player: null,
      leChangePlayer: null,
    }
  },
  computed: {
    isMobile() {
      return isMobile()
    },
  },
  methods: {
    async open(
      markerInfo,
      dialogWidth = '760px',
      fullscreen = false,
      dTop = '1vh'
    ) {
      this.markerInfo = markerInfo
      this.title = markerInfo.title || null
      this.fullscreen = fullscreen
      this.dTop = dTop
      this.width = dialogWidth
      this.visible = true
      if (!this.result) {
        const result = await getCameraLiveUrl(markerInfo.device_full_id)
        if (!result) {
          return false
        }
      }
      this.videoUrl = this.result.url


      this.initEasyPlayer()
    },
    initEasyPlayer() {
      if (this.videoUrl) {
        this.muted = true
        this.live = true
        this.$nextTick(() => {
          this.autoplay = true
        })
      }
    },
    onPlayError() {},
    onBeforeDialogClose() {
      console.log('his.$refs.camera_player:', this.$refs.camera_player)
      if (this.$refs.camera_player) {
        // TODO： 销毁播放器不太成功
        this.$refs.camera_player.destroyPlayer()
      }
      this.videoUrl = ''
      return true
    },
    onDialogClose() {
      this.onBeforeDialogClose()
      this.$emit('onDialogClose')
    },
  },
}
</script>
